/* ===================== 眠窗 · 多语言框架 =====================
   用法：
     I18N.t('key')              取一条界面文案
     I18N.sceneLabel('lightRain') 取某个场景/声音的名字
     I18N.setLang('en')         切换语言（会存进 localStorage，下次打开记住）
     I18N.applyToDOM()          把当前语言套用到所有带 data-i18n 属性的元素上

   加新语言：在下面 DICT 里复制一份 'en' 抄一遍字段名，把值换成目标语言即可，
   然后去 LANG_NAMES 里加一行"语言代码: 本地语言名"，语言切换器会自动出现这个选项。

   ⚠️ 除中文/英文外，其余语言由本项目直接给出常用界面短语的翻译，建议正式上架前
   找对应语言的母语者做一次校对，尤其是阿拉伯语(ar)和乌尔都语(ur)——这两个是从右到左
   书写(RTL)，本文件已经处理了 dir="rtl" 的自动切换，但如果以后新增自定义排版元素，
   仍需要人工确认视觉上有没有需要镜像的地方。
================================================================= */
