      helpRefundIntro:'Es tut uns leid, dass die Erfahrung nicht Ihren Erwartungen entsprach. Rückerstattungen für Käufe/Abonnements werden direkt von Apple oder Google abgewickelt — wir können selbst keine Rückerstattungen ausstellen —, aber hier ist eine Schritt-für-Schritt-Anleitung. Das dauert meist nur wenige Minuten.',
