      helpRefundIosSteps:'Öffnen Sie reportaproblem.apple.com und melden Sie sich mit der beim Kauf verwendeten Apple-ID an\nSuchen Sie die Bestellung „Night Window" und tippen Sie auf „Problem melden"\nWählen Sie den Grund aus und senden Sie ab — Apple bearbeitet dies meist innerhalb von 24-48 Stunden',
