      diamondDetailToggle:'Alle Diamond-Vorteile ansehen ▾', diamondDetailToggleOpen:'Einklappen ▴',
      diamondPerksList:'6 exklusive Nacht-Themes zur Auswahl, jederzeit wechselbar – ein ganz eigener Look, anders als jede andere Stufe\nPrivate, sorgfältig abgestimmte Sound-Presets, die es sonst nirgendwo gibt\nBis zu 60 gespeicherte Mixe (Standardstufen sind auf 8 begrenzt – in der Praxis erreichen Sie dieses Limit kaum)\nEin privater Kanal des Gründers – Sie erfahren als Erste(r), was wir als Nächstes vorhaben\nEin Diamond-Abzeichen auf allem, was Sie teilen\nEin „persönlicher Wunsch“ pro Jahr – wir prüfen ihn persönlich und ernsthaft (ohne Umsetzungsgarantie)\nEin privater Diamond-Support – wir streben eine Antwort innerhalb von 24 Stunden an\nIhr Preis ist lebenslang festgeschrieben, unabhängig davon, was neue Mitglieder später zahlen\nFalls jemals Werbung eingeführt wird, sind Diamond-Mitglieder dauerhaft davon ausgenommen',
