      greetToggleTitle:'स्नेहिल संदेश', greetToggleSub:'ऐप खोलने पर कभी-कभी एक वाक्य दिखता है। कभी भी बंद कर सकते हैं।',
      buyoutPrefix:'आप लगातार ', buyoutSuffix:' दिनों से इस्तेमाल कर रहे हैं। अगर लंबे समय तक इस्तेमाल करने का सोच रहे हैं, तो एक बार का भुगतान करके आगे नवीनीकरण की चिंता खत्म हो सकती है।',
      buyoutCta:'लाइफटाइम कीमत देखें', buyoutPaywallBody:'एक बार भुगतान करें, हमेशा के लिए इस्तेमाल करें — फिर नवीनीकरण की चिंता नहीं। बाद में जोड़े जाने वाले नए दृश्य भी शामिल हैं (संख्या का वादा नहीं, लेकिन हम जोड़ते रहते हैं)। नियमित उपयोग करने वालों के लिए यह अक्सर बेहतर होता है।',
      manageBadgeActive:'आप अभी सब्सक्राइबर हैं। अगर लंबे समय तक इस्तेमाल करने का सोच रहे हैं, तो लाइफटाइम खरीद ज़्यादा सही हो सकती है — एक बार भुगतान करें और फिर कभी नवीनीकरण की चिंता नहीं।',
      manageBadgeLifetime:'आपके पास लाइफटाइम सदस्यता है — धन्यवाद। अब इसके बारे में फिर कभी सोचने की ज़रूरत नहीं। अगर आप और भी खास अनुभव चाहते हैं, तो डायमंड💎 स्तर देख सकते हैं।',
      diamondUpgradeCta:'डायमंड💎 देखें',
      manageBadgeOpenStore:'सब्सक्रिप्शन सेटिंग्स खोलें',
      uninstallNotCancelNotice:'ऐप अनइंस्टॉल करने से सब्सक्रिप्शन अपने आप रद्द नहीं होती। भुगतान रोकने के लिए, अनइंस्टॉल करने से पहले अपनी App Store/Google Play खाता सेटिंग में सब्सक्रिप्शन रद्द करें।',
      manageBadgeYearlyDowngradeHint:'अगर वार्षिक प्लान भारी लग रहा है, तो आप सब्सक्रिप्शन सेटिंग्स में मासिक प्लान पर भी स्विच कर सकते हैं — रद्द करना ही एकमात्र विकल्प नहीं है।',
      retentionApology1:'माफ़ कीजिए कि हम आपको अच्छा अनुभव नहीं दे पाए — क्या आप पहले कोई और सब्सक्रिप्शन विकल्प देखना चाहेंगे?',
      retentionApology2:'अगर आप चाहें, तो जाने से पहले कोई दूसरा प्लान आज़मा सकते हैं — रद्द करना ही एकमात्र रास्ता नहीं है।',
      retentionApology3:'जाने से पहले एक बात पूछना चाहते हैं: क्या कोई दूसरा प्लान आपके लिए बेहतर रहेगा?',
