      helpRefundTitle:'सहायता और रिफ़ंड',
      helpRefundIntro:'माफ़ कीजिए कि यह अनुभव आपकी उम्मीद के मुताबिक नहीं रहा। खरीद/सदस्यता के रिफ़ंड सीधे Apple या Google द्वारा संभाले जाते हैं — हमारे पास खुद रिफ़ंड जारी करने की क्षमता नहीं है — लेकिन यहाँ एक स्टेप-बाय-स्टेप गाइड है। आम तौर पर इसमें बस कुछ मिनट लगते हैं।',
      helpRefundIosTitle:'Apple App Store उपयोगकर्ता',
      helpRefundIosSteps:'reportaproblem.apple.com खोलें और जिस Apple ID से खरीदा था उससे साइन इन करें\n"Night Window" का ऑर्डर ढूंढें और "समस्या की रिपोर्ट करें" पर टैप करें\nकारण चुनें और सबमिट करें — Apple आमतौर पर 24-48 घंटों में इसे प्रोसेस करता है',
