      helpRefundAndroidTitle:'Google Play उपयोगकर्ता',
      helpRefundAndroidSteps:'Google Play Store ऐप खोलें, अपने प्रोफ़ाइल आइकन पर टैप करें, फिर "पेमेंट और सदस्यताएं"\n"Night Window" का ऑर्डर ढूंढें और "समस्या की रिपोर्ट करें" या "रिफ़ंड का अनुरोध करें" पर टैप करें\nकारण चुनें और सबमिट करें — Google आमतौर पर कुछ दिनों में इसे प्रोसेस करता है',
