      customSoundDisclaimer:'यह ऑडियो केवल आपके फ़ोन पर रहेगा — हम इसे कभी अपलोड नहीं करते और इसकी सामग्री जांचने में सक्षम नहीं हैं। कृपया ऐसा संगीत न जोड़ें जिसके अधिकार आपके पास नहीं हैं, और न ही कोई गैरकानूनी, धार्मिक रूप से उग्रवादी, हिंसक या भयावह सामग्री जोड़ें। आपके द्वारा जोड़ी गई सामग्री की ज़िम्मेदारी आपकी है। जारी रखें?',
