      diamondPerksTeaser:'विशेष थीम · निजी साउंड प्रीसेट · फ़ाउंडर से सीधा संपर्क · और भी बहुत कुछ',
      diamondDetailToggle:'डायमंड की सभी सुविधाएं देखें ▾', diamondDetailToggleOpen:'छोटा करें ▴',
      diamondPerksList:'6 विशेष रात्रि थीम में से चुनें, कभी भी बदलें — हर दूसरे स्तर से बिल्कुल अलग दिखावट\nनिजी, ध्यान से तैयार किए गए साउंड प्रीसेट, जो कहीं और नहीं मिलेंगे\n60 तक सेव किए गए मिक्स (बाकी स्तरों में सिर्फ 8 तक सीमा है — सामान्य उपयोग में आप शायद इस सीमा तक कभी नहीं पहुंचेंगे)\nफ़ाउंडर का निजी चैनल — नई सुविधाओं के बारे में आपको सबसे पहले बताया जाएगा\nजब भी आप शेयर करें, उस पर डायमंड बैज\nसाल में 1 बार "विशेष गुज़ारिश" — हम इसे गंभीरता से और व्यक्तिगत रूप से देखेंगे (पूरा करने की गारंटी नहीं)\nनिजी डायमंड सपोर्ट — हमारा लक्ष्य 24 घंटे के भीतर जवाब देना है\nआपकी कीमत हमेशा के लिए तय, भविष्य में नए सदस्यों से चाहे जो भी लिया जाए\nभविष्य में कभी विज्ञापन आए, तो डायमंड सदस्य हमेशा के लिए उससे मुक्त रहेंगे',
      diamondLoungeOpenCta:'विशेष स्थान में जाएं',
