      downgradePurchaseBlocked:'आपके पास इससे ऊँचा सदस्यता स्तर पहले से मौजूद है। इसे खरीदने से आपके मौजूदा लाभ खत्म हो जाते, इसलिए हमने आपसे शुल्क नहीं लिया। यदि आप वास्तव में स्तर बदलना चाहते हैं, तो कृपया पहले सपोर्ट से संपर्क करें।',
