      videoStallHint:'ਵੀਡੀਓ ਲੋਡ ਹੋ ਰਿਹਾ ਹੈ — ਆਵਾਜ਼ ਪ੍ਰਭਾਵਿਤ ਨਹੀਂ ਹੋਵੇਗੀ',
      lockBtnTitle:'ਅਣਜਾਣ ਸਪਰਸ਼ ਤੋਂ ਬਚਾਅ ਲਈ ਸਕ੍ਰੀਨ ਲਾਕ ਕਰੋ',
      lockShieldHint:'ਲਾਕ ਕੀਤਾ ਗਿਆ · ਅਨਲਾਕ ਕਰਨ ਲਈ ਸਕ੍ਰੀਨ ਤੇ ਦੋ ਵਾਰ ਟੈਪ ਕਰੋ',
      cellularTitle:'ਤੁਸੀਂ ਮੋਬਾਈਲ ਡੇਟਾ ਵਰਤ ਰਹੇ ਹੋ',
      cellularBody:'ਇਸ ਦ੍ਰਿਸ਼ ਦਾ ਵੀਡੀਓ ਡਾਊਨਲੋਡ ਕਰਨਾ ਪਵੇਗਾ ਜਿਸ ਨਾਲ ਤੁਹਾਡਾ ਮੋਬਾਈਲ ਡੇਟਾ ਖਰਚ ਹੋਵੇਗਾ। Wi-Fi ਦੀ ਸਲਾਹ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ, ਜਾਂ ਡਾਊਨਲੋਡ ਜਾਰੀ ਰੱਖਣ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ।',
      cellularAllow:'ਡਾਊਨਲੋਡ ਦੀ ਇਜਾਜ਼ਤ ਦਿਓ',
      cellularCancel:'ਰੱਦ ਕਰੋ',
      shareMessage:'ਮੈਂ ਸੌਣ ਤੋਂ ਪਹਿਲਾਂ ਆਰਾਮ ਲਈ "ਨੀਂਦ ਦੀ ਖਿੜਕੀ" ਵਰਤ ਰਿਹਾ/ਰਹੀ ਹਾਂ, ਦ੍ਰਿਸ਼ ਅਤੇ ਆਵਾਜ਼ਾਂ ਬਹੁਤ ਸ਼ਾਂਤ ਕਰਨ ਵਾਲੀਆਂ ਹਨ। ਸੋਚਿਆ ਤੁਹਾਨੂੰ ਵੀ ਪਸੰਦ ਆਵੇਗਾ:',
      streakPrefix:'ਤੁਸੀਂ ਨੀਂਦ ਦੀ ਖਿੜਕੀ ਲਗਾਤਾਰ ', streakSuffix:' ਰਾਤਾਂ ਤੋਂ ਵਰਤੀ ਹੈ। ਕਿਸੇ ਦੋਸਤ ਨਾਲ ਸਾਂਝੀ ਕਰੋ ਜਿਸਨੂੰ ਬਿਹਤਰ ਨੀਂਦ ਦੀ ਲੋੜ ਹੈ?',
      shareBannerCta:'ਦੋਸਤ ਨਾਲ ਸਾਂਝਾ ਕਰੋ', shareBannerDismiss:'ਹੁਣੇ ਨਹੀਂ',
      greet1:'ਤੁਸੀਂ ਵਾਪਸ ਆ ਗਏ। ਅੱਜ ਦਾ ਦਿਨ ਲੰਮਾ ਰਿਹਾ ਹੋਵੇਗਾ।', greet2:'ਹੁਣ ਹੋਰ ਕੁਝ ਸੋਚਣ ਦੀ ਲੋੜ ਨਹੀਂ।', greet3:'ਇੱਥੇ ਬਹੁਤ ਸ਼ਾਂਤੀ ਹੈ। ਆਰਾਮ ਨਾਲ ਰਹੋ।',
      greetLateNight:'ਇਸ ਵੇਲੇ ਤੱਕ ਜਾਗ ਰਹੇ ਹੋ? ਕੋਈ ਗੱਲ ਨਹੀਂ, ਮੈਂ ਥੋੜ੍ਹੀ ਦੇਰ ਨਾਲ ਹਾਂ।',
      greetToggleTitle:'ਨਿੱਘੇ ਸ਼ਬਦ', greetToggleSub:'ਐਪ ਖੋਲ੍ਹਣ ਤੇ ਕਦੇ-ਕਦੇ ਇੱਕ ਵਾਕ ਦਿਖਦਾ ਹੈ। ਕਦੇ ਵੀ ਬੰਦ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।',
      buyoutPrefix:'ਤੁਸੀਂ ਲਗਾਤਾਰ ', buyoutSuffix:' ਦਿਨਾਂ ਤੋਂ ਵਰਤ ਰਹੇ ਹੋ। ਜੇ ਲੰਬੇ ਸਮੇਂ ਤੱਕ ਵਰਤਣ ਦਾ ਸੋਚ ਰਹੇ ਹੋ, ਤਾਂ ਇੱਕ ਵਾਰ ਦੀ ਖਰੀਦ ਨਾਲ ਨਵੀਨੀਕਰਨ ਦੀ ਚਿੰਤਾ ਖਤਮ ਹੋ ਸਕਦੀ ਹੈ।',
      buyoutCta:'ਲਾਈਫਟਾਈਮ ਕੀਮਤ ਦੇਖੋ', buyoutPaywallBody:'ਇੱਕ ਵਾਰ ਭੁਗਤਾਨ ਕਰੋ, ਹਮੇਸ਼ਾ ਵਰਤੋ — ਫਿਰ ਨਵੀਨੀਕਰਨ ਦੀ ਚਿੰਤਾ ਨਹੀਂ। ਬਾਅਦ ਵਿੱਚ ਸ਼ਾਮਲ ਕੀਤੇ ਨਵੇਂ ਦ੍ਰਿਸ਼ ਵੀ ਇਸ ਵਿੱਚ ਸ਼ਾਮਲ ਹਨ (ਗਿਣਤੀ ਦਾ ਵਾਅਦਾ ਨਹੀਂ, ਪਰ ਅਸੀਂ ਜੋੜਦੇ ਰਹਿੰਦੇ ਹਾਂ)। ਨਿਯਮਤ ਵਰਤੋਂ ਕਰਨ ਵਾਲਿਆਂ ਲਈ ਇਹ ਅਕਸਰ ਬਿਹਤਰ ਸੌਦਾ ਹੁੰਦਾ ਹੈ।',
      manageBadgeActive:'ਤੁਸੀਂ ਹੁਣ ਸਬਸਕ੍ਰਾਈਬਰ ਹੋ। ਜੇ ਲੰਬੇ ਸਮੇਂ ਤੱਕ ਵਰਤਣ ਦਾ ਸੋਚ ਰਹੇ ਹੋ, ਤਾਂ ਲਾਈਫਟਾਈਮ ਖਰੀਦ ਵਧੇਰੇ ਢੁਕਵੀਂ ਹੋ ਸਕਦੀ ਹੈ — ਇੱਕ ਵਾਰ ਭੁਗਤਾਨ ਕਰੋ, ਫਿਰ ਕਦੇ ਵੀ ਨਵੀਨੀਕਰਨ ਬਾਰੇ ਸੋਚਣ ਦੀ ਲੋੜ ਨਹੀਂ।',
      manageBadgeLifetime:'ਤੁਹਾਡੇ ਕੋਲ ਲਾਈਫਟਾਈਮ ਮੈਂਬਰਸ਼ਿਪ ਹੈ — ਧੰਨਵਾਦ। ਹੁਣ ਇਸ ਬਾਰੇ ਸੋਚਣ ਦੀ ਲੋੜ ਨਹੀਂ। ਜੇ ਤੁਸੀਂ ਹੋਰ ਵੀ ਖਾਸ ਅਨੁਭਵ ਚਾਹੁੰਦੇ ਹੋ, ਤਾਂ ਡਾਇਮੰਡ💎 ਪੱਧਰ ਦੇਖ ਸਕਦੇ ਹੋ।',
      diamondUpgradeCta:'ਡਾਇਮੰਡ💎 ਦੇਖੋ',
      manageBadgeOpenStore:'ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਸੈਟਿੰਗਾਂ ਖੋਲ੍ਹੋ',
      uninstallNotCancelNotice:'ਐਪ ਅਣਇੰਸਟਾਲ ਕਰਨ ਨਾਲ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਆਪੇ ਰੱਦ ਨਹੀਂ ਹੁੰਦੀ। ਭੁਗਤਾਨ ਰੋਕਣ ਲਈ, ਅਣਇੰਸਟਾਲ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣੀ App Store/Google Play ਖਾਤਾ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਰੱਦ ਕਰੋ।',
      manageBadgeYearlyDowngradeHint:'ਜੇ ਸਾਲਾਨਾ ਪਲਾਨ ਮਹਿੰਗਾ ਲੱਗ ਰਿਹਾ ਹੈ, ਤਾਂ ਤੁਸੀਂ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਮਹੀਨਾਵਾਰ ਪਲਾਨ \'ਤੇ ਵੀ ਬਦਲ ਸਕਦੇ ਹੋ — ਰੱਦ ਕਰਨਾ ਹੀ ਇੱਕੋ ਬਦਲ ਨਹੀਂ ਹੈ।',
      retentionApology1:'ਮੁਆਫ਼ ਕਰਨਾ ਕਿ ਅਸੀਂ ਤੁਹਾਨੂੰ ਵਧੀਆ ਤਜਰਬਾ ਨਹੀਂ ਦੇ ਸਕੇ — ਕੀ ਤੁਸੀਂ ਪਹਿਲਾਂ ਕੋਈ ਹੋਰ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਤਰੀਕਾ ਦੇਖਣਾ ਚਾਹੋਗੇ?',
      retentionApology2:'ਜੇ ਤੁਸੀਂ ਚਾਹੋ, ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਕੋਈ ਹੋਰ ਪਲਾਨ ਵੀ ਅਜ਼ਮਾ ਸਕਦੇ ਹੋ — ਰੱਦ ਕਰਨਾ ਹੀ ਇੱਕੋ ਰਾਹ ਨਹੀਂ ਹੈ।',
      retentionApology3:'ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਗੱਲ ਪੁੱਛਣੀ ਹੈ: ਕੀ ਕੋਈ ਹੋਰ ਪਲਾਨ ਤੁਹਾਡੇ ਲਈ ਬਿਹਤਰ ਰਹੇਗਾ?',
      retentionSeeOptionsCta:'ਹੋਰ ਵਿਕਲਪ ਦੇਖੋ',
      retentionContinueCta:'ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਸੈਟਿੰਗਾਂ ਵੱਲ ਜਾਰੀ ਰੱਖੋ',
      newBadge:'ਨਵਾਂ',
      winBackReminderBody:'ਤੁਸੀਂ ਕਾਫ਼ੀ ਸਮੇਂ ਤੋਂ ਨੀਂਦ ਦੀ ਖਿੜਕੀ ਨਹੀਂ ਖੋਲ੍ਹਿਆ — ਸਮਾਂ ਮਿਲਣ \'ਤੇ ਇੱਕ ਵਾਰ ਸੁਣੋ।',
      annualReportNotifBody:'ਇਸ ਸਾਲ, ਨੀਂਦ ਦੀ ਖਿੜਕੀ ਲਗਭਗ {nights} ਰਾਤਾਂ ਅਤੇ ਕੁੱਲ {hours} ਘੰਟੇ ਤੁਹਾਡੇ ਨਾਲ ਰਿਹਾ — ਇਸ ਸਾਲ ਸਾਡਾ ਹਿੱਸਾ ਬਣਨ ਲਈ ਧੰਨਵਾਦ।',
      winBackBlackFridayNotifBody:'ਕਾਫ਼ੀ ਸਮਾਂ ਹੋ ਗਿਆ — ਬਲੈਕ ਫਰਾਈਡੇ ਦੌਰਾਨ ਅਸੀਂ ਅਕਸਰ ਸੀਮਤ ਸਮੇਂ ਦੀਆਂ ਪੇਸ਼ਕਸ਼ਾਂ ਦਿੰਦੇ ਹਾਂ, ਸਮਾਂ ਮਿਲਣ \'ਤੇ ਦੇਖ ਲਓ।',
      annualReportTitle:'ਇਸ ਸਾਲ ਨੀਂਦ ਦੀ ਖਿੜਕੀ ਨੂੰ ਆਪਣੇ ਨਾਲ ਰੱਖਣ ਲਈ ਧੰਨਵਾਦ',
