      annualReportLongestStreakLabel:'ਸਭ ਤੋਂ ਲੰਮਾ ਲਗਾਤਾਰ ਸਮਾਂ (ਦਿਨ)',
      annualReportFavoriteSceneLabel:'ਸਭ ਤੋਂ ਵੱਧ ਸੁਣੀ ਗਈ ਆਵਾਜ਼',
      annualReportNoDataYet:'ਅਜੇ ਲੋੜੀਂਦਾ ਸੁਣਨ ਦਾ ਇਤਿਹਾਸ ਨਹੀਂ ਹੈ — ਕੁਝ ਹੋਰ ਰਾਤਾਂ ਬਾਅਦ ਵਾਪਸ ਆਓ।',
      annualReportGiftTitle:'ਸਾਲਗਿਰ੍ਹਾ ਦਾ ਤੋਹਫ਼ਾ · ਇੱਕ ਸੀਨ ਅਨਲੌਕ ਕਰੋ',
      annualReportGiftDesc:'ਇਸ ਵੇਲੇ ਲੌਕ ਕੀਤਾ ਕੋਈ ਇੱਕ ਸੀਨ ਚੁਣੋ ਅਤੇ ਇਸਨੂੰ 7 ਦਿਨਾਂ ਲਈ ਮੁਫ਼ਤ ਅਨਲੌਕ ਕਰੋ — ਹਰ ਰੀਨਿਊਅਲ ਸਾਈਕਲ ਵਿੱਚ ਇੱਕ ਵਾਰ।',
      annualReportGiftClaimBtn:'7 ਦਿਨਾਂ ਦਾ ਅਨਲੌਕ ਪ੍ਰਾਪਤ ਕਰੋ',
      annualReportGiftActiveStatus:'\'{scene}\' ਅਨਲੌਕ ਹੈ — {days} ਦਿਨ ਬਾਕੀ।',
      annualReportGiftUsedUpStatus:'ਤੁਸੀਂ ਇਸ ਸਾਈਕਲ ਦਾ ਤੋਹਫ਼ਾ ਪਹਿਲਾਂ ਹੀ ਲੈ ਲਿਆ ਹੈ — ਅਗਲੀ ਰੀਨਿਊਅਲ ਤੋਂ ਬਾਅਦ ਦੇਖੋ।',
      lifetimeUpgradeBadge:'ਅੱਪਗ੍ਰੇਡ ਛੂਟ · ਸੀਮਤ ਸਮਾਂ',
      lifetimeUpgradeNote:'ਤੁਸੀਂ ਪਹਿਲਾਂ ਹੀ ਅਦਾ ਕੀਤੀ ਸਾਲਾਨਾ ਫੀਸ ਇਸ ਵਿੱਚ ਐਡਜਸਟ ਕੀਤੀ ਗਈ ਹੈ — ਸਿਰਫ਼ {price} ਹੋਰ ਦੇ ਕੇ ਲਾਈਫਟਾਈਮ ਵਿੱਚ ਅੱਪਗ੍ਰੇਡ ਕਰੋ, ਅੱਗੇ ਕੋਈ ਆਟੋ-ਰੀਨਿਊਅਲ ਨਹੀਂ।',
      retentionLifetimeUpgradeHint:'ਜੇ ਤੁਸੀਂ ਹਰ ਸਾਲ ਰੀਨਿਊ ਨਹੀਂ ਕਰਨਾ ਚਾਹੁੰਦੇ, ਤਾਂ ਸਿਰਫ਼ {price} ਹੋਰ ਦੇ ਕੇ ਲਾਈਫਟਾਈਮ ਵਿੱਚ ਅੱਪਗ੍ਰੇਡ ਕਰੋ — ਅਤੇ ਫਿਰ ਕਦੇ ਰੀਨਿਊਅਲ ਬਾਰੇ ਨਾ ਸੋਚੋ।',
      annualReportUpgradeOfferNotifSuffix:'ਹੁਣ ਸਿਰਫ਼ {price} ਹੋਰ ਦੇ ਕੇ ਲਾਈਫਟਾਈਮ ਵਿੱਚ ਅੱਪਗ੍ਰੇਡ ਕਰੋ, ਅੱਗੇ ਰੀਨਿਊਅਲ ਦੀ ਚਿੰਤਾ ਨਹੀਂ।',
      lifetimeUpgradeCta:'ਹੁਣੇ ਅੱਪਗ੍ਰੇਡ ਕਰੋ',
      helpRefundLinkLabel:'ਮਦਦ ਅਤੇ ਰਿਫੰਡ',
      helpRefundTitle:'ਮਦਦ ਅਤੇ ਰਿਫੰਡ',
      helpRefundIntro:'ਮੁਆਫ਼ ਕਰਨਾ ਕਿ ਇਹ ਤਜਰਬਾ ਤੁਹਾਡੀ ਉਮੀਦ ਮੁਤਾਬਕ ਨਹੀਂ ਰਿਹਾ। ਖਰੀਦ/ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਦੇ ਰਿਫੰਡ ਸਿੱਧੇ Apple ਜਾਂ Google ਵੱਲੋਂ ਸੰਭਾਲੇ ਜਾਂਦੇ ਹਨ — ਸਾਡੇ ਕੋਲ ਖੁਦ ਰਿਫੰਡ ਜਾਰੀ ਕਰਨ ਦੀ ਸਮਰੱਥਾ ਨਹੀਂ ਹੈ — ਪਰ ਇਹ ਰਹੀ ਕਦਮ-ਦਰ-ਕਦਮ ਗਾਈਡ। ਆਮ ਤੌਰ \'ਤੇ ਇਸ ਵਿੱਚ ਸਿਰਫ਼ ਕੁਝ ਮਿੰਟ ਲੱਗਦੇ ਹਨ।',
      helpRefundIosTitle:'Apple App Store ਵਰਤੋਂਕਾਰ',
      helpRefundIosSteps:'reportaproblem.apple.com ਖੋਲ੍ਹੋ ਅਤੇ ਜਿਸ Apple ID ਨਾਲ ਖਰੀਦਿਆ ਸੀ ਉਸ ਨਾਲ ਸਾਈਨ ਇਨ ਕਰੋ\n"Night Window" ਦਾ ਆਰਡਰ ਲੱਭੋ ਅਤੇ "ਸਮੱਸਿਆ ਦੀ ਰਿਪੋਰਟ ਕਰੋ" ਤੇ ਟੈਪ ਕਰੋ\nਕਾਰਨ ਚੁਣੋ ਅਤੇ ਜਮ੍ਹਾਂ ਕਰੋ — Apple ਆਮ ਤੌਰ \'ਤੇ 24-48 ਘੰਟਿਆਂ ਵਿੱਚ ਇਸਨੂੰ ਪ੍ਰੋਸੈਸ ਕਰਦਾ ਹੈ',
      helpRefundIosBtn:'Apple ਦੇ ਰਿਫੰਡ ਪੇਜ \'ਤੇ ਜਾਓ',
      helpRefundAndroidTitle:'Google Play ਵਰਤੋਂਕਾਰ',
      helpRefundAndroidSteps:'Google Play Store ਐਪ ਖੋਲ੍ਹੋ, ਆਪਣੇ ਪ੍ਰੋਫਾਈਲ ਆਈਕਨ ਤੇ ਟੈਪ ਕਰੋ, ਫਿਰ "ਪੇਮੈਂਟਸ ਅਤੇ ਸਬਸਕ੍ਰਿਪਸ਼ਨਜ਼"\n"Night Window" ਦਾ ਆਰਡਰ ਲੱਭੋ ਅਤੇ "ਸਮੱਸਿਆ ਦੀ ਰਿਪੋਰਟ ਕਰੋ" ਜਾਂ "ਰਿਫੰਡ ਦੀ ਬੇਨਤੀ ਕਰੋ" ਤੇ ਟੈਪ ਕਰੋ\nਕਾਰਨ ਚੁਣੋ ਅਤੇ ਜਮ੍ਹਾਂ ਕਰੋ — Google ਆਮ ਤੌਰ \'ਤੇ ਕੁਝ ਦਿਨਾਂ ਵਿੱਚ ਇਸਨੂੰ ਪ੍ਰੋਸੈਸ ਕਰਦਾ ਹੈ',
      helpRefundAndroidBtn:'Google Play ਆਰਡਰ ਇਤਿਹਾਸ \'ਤੇ ਜਾਓ',
      helpRefundFallback:'ਜੇ ਕੋਈ ਜਵਾਬ ਨਾ ਮਿਲੇ, ਜਾਂ ਕੋਈ ਹੋਰ ਸਮੱਸਿਆ ਹੋਵੇ, ਤਾਂ ਸਿੱਧੇ ਸਾਡੇ ਨਾਲ ਸੰਪਰਕ ਕਰੋ — ਅਸੀਂ ਮਦਦ ਕਰਨ ਦੀ ਪੂਰੀ ਕੋਸ਼ਿਸ਼ ਕਰਾਂਗੇ।',
      helpRefundEmailBtn:'ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ',
