      diamondPerksList:'6 ਖ਼ਾਸ ਰਾਤ ਦੀਆਂ ਥੀਮਾਂ ਵਿੱਚੋਂ ਚੁਣੋ, ਕਦੇ ਵੀ ਬਦਲੋ — ਹਰ ਹੋਰ ਪੱਧਰ ਤੋਂ ਬਿਲਕੁਲ ਵੱਖਰੀ ਦਿੱਖ\nਨਿੱਜੀ, ਧਿਆਨ ਨਾਲ ਤਿਆਰ ਕੀਤੇ ਸਾਊਂਡ ਪ੍ਰੀਸੈੱਟ, ਜੋ ਹੋਰ ਕਿਤੇ ਨਹੀਂ ਮਿਲਣਗੇ\n60 ਤੱਕ ਸੇਵ ਕੀਤੇ ਮਿਕਸ (ਬਾਕੀ ਪੱਧਰਾਂ ਵਿੱਚ ਸਿਰਫ਼ 8 ਤੱਕ ਸੀਮਾ ਹੈ — ਆਮ ਵਰਤੋਂ ਵਿੱਚ ਤੁਸੀਂ ਸ਼ਾਇਦ ਇਸ ਸੀਮਾ ਤੱਕ ਕਦੇ ਨਹੀਂ ਪਹੁੰਚੋਗੇ)\nਫ਼ਾਊਂਡਰ ਦਾ ਨਿੱਜੀ ਚੈਨਲ — ਨਵੀਆਂ ਸਹੂਲਤਾਂ ਬਾਰੇ ਤੁਹਾਨੂੰ ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਦੱਸਿਆ ਜਾਵੇਗਾ\nਜਦੋਂ ਵੀ ਤੁਸੀਂ ਸ਼ੇਅਰ ਕਰੋ, ਉਸ ਉੱਤੇ ਡਾਇਮੰਡ ਬੈਜ\nਸਾਲ ਵਿੱਚ 1 ਵਾਰ "ਖ਼ਾਸ ਬੇਨਤੀ" — ਅਸੀਂ ਇਸਨੂੰ ਗੰਭੀਰਤਾ ਨਾਲ ਤੇ ਖ਼ੁਦ ਦੇਖਾਂਗੇ (ਪੂਰਾ ਕਰਨ ਦੀ ਗਰੰਟੀ ਨਹੀਂ)\nਨਿੱਜੀ ਡਾਇਮੰਡ ਸਹਾਇਤਾ — ਸਾਡਾ ਟੀਚਾ 24 ਘੰਟਿਆਂ ਵਿੱਚ ਜਵਾਬ ਦੇਣਾ ਹੈ\nਤੁਹਾਡੀ ਕੀਮਤ ਸਦਾ ਲਈ ਤੈਅ, ਭਵਿੱਖ ਵਿੱਚ ਨਵੇਂ ਮੈਂਬਰਾਂ ਤੋਂ ਭਾਵੇਂ ਜੋ ਵੀ ਲਿਆ ਜਾਵੇ\nਭਵਿੱਖ ਵਿੱਚ ਕਦੇ ਵਿਗਿਆਪਨ ਆਏ, ਤਾਂ ਡਾਇਮੰਡ ਮੈਂਬਰ ਸਦਾ ਲਈ ਉਸ ਤੋਂ ਮੁਕਤ ਰਹਿਣਗੇ',
