      previewEndedBody:'"{scene}" ਮੈਂਬਰ ਸਮੱਗਰੀ ਹੈ। ਮੈਂਬਰ ਪੂਰੀ ਰਾਤ ਬਿਨਾਂ ਰੁਕਾਵਟ ਸੁਣ ਸਕਦੇ ਹਨ। ਸਾਲਾਨਾ ਪਲੈਨ ਵਿੱਚ 3 ਦਿਨ ਦਾ ਮੁਫ਼ਤ ਟ੍ਰਾਇਲ ਸ਼ਾਮਲ ਹੈ, ਕਦੇ ਵੀ ਰੱਦ ਕਰੋ।', previewAgain:'ਫਿਰ ਸੁਣੋ', previewUpgrade:'ਮੈਂਬਰਸ਼ਿਪ ਜਾਣੋ', mixTrackLimit:'ਮੁਫ਼ਤ ਵਰਜ਼ਨ ਵਿੱਚ ਇਕੋ ਵੇਲੇ 2 ਆਵਾਜ਼ਾਂ ਮਿਕਸ ਹੋ ਸਕਦੀਆਂ ਹਨ। ਅਨਲਿਮਿਟਡ ਟ੍ਰੈਕ ਲਈ ਅਪਗ੍ਰੇਡ ਕਰੋ।', morningTitle:'ਕੱਲ੍ਹ ਰਾਤ ਨੀਂਦ ਕਿਵੇਂ ਰਹੀ?', morningGood:'ਬਹੁਤ ਵਧੀਆ', morningOk:'ਠੀਕ-ਠਾਕ', morningBad:'ਫਿਰ ਨੀਂਦ ਠੀਕ ਨਹੀਂ', morningGoodBody:'ਖੁਸ਼ੀ ਦੀ ਗੱਲ ਹੈ। ਹੋਰ ਆਵਾਜ਼ਾਂ ਅਤੇ ਦ੍ਰਿਸ਼ ਅਜ਼ਮਾਉਣਾ ਚਾਹੋਗੇ? ਮੈਂਬਰ ਸਭ ਕੁਝ ਪੂਰੀ ਰਾਤ ਸੁਣ ਸਕਦੇ ਹਨ। ਸਾਲਾਨਾ ਪਲੈਨ ਵਿੱਚ 3 ਦਿਨ ਮੁਫ਼ਤ ਟ੍ਰਾਇਲ ਹੈ।', morningBadBody:'ਰਾਤ ਚੰਗੀ ਨਹੀਂ ਗਈ, ਅਫ਼ਸੋਸ ਹੈ। ਅੱਜ ਰਾਤ ਕੋਈ ਵੱਖਰੀ ਸਾਉਂਡ ਬਣਤਰ ਅਜ਼ਮਾਈਏ? ਮੈਂਬਰ ਸੀਨ ਪੂਰੀ ਰਾਤ ਸਾਥ ਦਿੰਦੇ ਹਨ। ਸਾਲਾਨਾ ਪਲੈਨ ਵਿੱਚ 3 ਦਿਨ ਮੁਫ਼ਤ ਟ੍ਰਾਇਲ, ਕਦੇ ਵੀ ਰੱਦ ਕਰੋ।', morningCta:'ਮੈਂਬਰਸ਼ਿਪ ਜਾਣੋ', morningLater:'ਬਾਅਦ ਵਿੱਚ', // v5 免费线·清醒预览制（2026-10-16 定稿，规格见 closed-testing-plan.md）
