      lifetimeCancelSubReminder:'ਲਾਈਫਟਾਈਮ ਖਰੀਦ ਪੂਰੀ ਹੋਈ! ਜੇ ਤੁਹਾਡੀ ਪਹਿਲਾਂ ਤੋਂ ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਚੱਲ ਰਹੀ ਸੀ, ਤਾਂ ਉਸਨੂੰ ਸਿਸਟਮ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਰੱਦ ਕਰਨਾ ਨਾ ਭੁੱਲੋ — ਨਹੀਂ ਤਾਂ ਉਸ ਲਈ ਵੀ ਖਰਚਾ ਜਾਰੀ ਰਹੇਗਾ।',
