      diamondPerksTeaser:'Tema eksklusif · Preset suara pribadi · Jalur langsung ke pendiri · dan masih banyak lagi',
      diamondDetailToggle:'Lihat semua keistimewaan Diamond ▾', diamondDetailToggleOpen:'Tutup ▴',
      diamondPerksList:'6 tema malam eksklusif untuk dipilih, bisa diganti kapan saja — tampilan yang sepenuhnya berbeda dari tingkat lainnya\nPreset suara pribadi yang diracik dengan cermat, tidak tersedia di tempat lain\nHingga 60 mix tersimpan (tingkat standar dibatasi 8 — dalam pemakaian normal, Anda kemungkinan besar tidak akan pernah mencapai batas ini)\nSaluran pribadi dari pendiri — Anda mengetahui apa yang sedang kami kerjakan lebih dulu dari siapa pun\nLencana Diamond pada apa pun yang Anda bagikan\nSatu "permintaan khusus" per tahun — kami akan mempertimbangkannya secara pribadi dan serius (tanpa janji akan diwujudkan)\nDukungan Diamond pribadi — kami berusaha membalas dalam 24 jam\nHarga Anda terkunci seumur hidup, berapa pun yang dikenakan pada anggota baru nantinya\nJika suatu saat iklan diperkenalkan, anggota Diamond akan dikecualikan secara permanen',
