      diamondPerksTeaser:'Giao diện độc quyền · Cấu hình âm thanh riêng · Kênh liên lạc trực tiếp với nhà sáng lập · và nhiều hơn nữa',
      diamondDetailToggle:'Xem tất cả đặc quyền Diamond ▾', diamondDetailToggleOpen:'Đóng lại ▴',
      diamondPerksList:'6 giao diện đêm độc quyền để lựa chọn, có thể đổi bất cứ lúc nào — một trải nghiệm hoàn toàn khác biệt so với các gói còn lại\nCấu hình âm thanh riêng được tuyển chọn kỹ lưỡng, không có ở nơi khác\nLưu được tối đa 60 hỗn hợp (gói thường chỉ 8 — với cách dùng thông thường, bạn khó có thể chạm tới giới hạn này)\nKênh riêng từ nhà sáng lập — bạn biết trước mọi cập nhật sớm hơn bất kỳ ai\nHuy hiệu Diamond trên mọi nội dung bạn chia sẻ\nMột lượt "yêu cầu riêng" mỗi năm — chúng tôi sẽ xem xét nghiêm túc và cá nhân (không hứa chắc sẽ thực hiện)\nHỗ trợ Diamond riêng — chúng tôi sẽ cố gắng phản hồi trong 24 giờ\nGiá của bạn được giữ nguyên vĩnh viễn, dù sau này thành viên mới phải trả bao nhiêu\nNếu sau này ứng dụng có quảng cáo, thành viên Diamond sẽ luôn được miễn trừ',
