      previewEndedBody:'"{scene}" là nội dung dành cho thành viên. Thành viên nghe suốt đêm không gián đoạn. Gói năm kèm 3 ngày dùng thử miễn phí, hủy bất cứ lúc nào.', previewAgain:'Nghe lại', previewUpgrade:'Tìm hiểu gói thành viên', mixTrackLimit:'Bản miễn phí trộn tối đa 2 âm thanh cùng lúc. Nâng cấp để không giới hạn track.', morningTitle:'Đêm qua bạn ngủ thế nào?', morningGood:'Rất ngon', morningOk:'Tạm ổn', morningBad:'Vẫn ngủ không ngon', morningGoodBody:'Thật tuyệt. Muốn thử thêm nhiều âm thanh và khung cảnh? Thành viên nghe mọi nội dung suốt đêm. Gói năm kèm 3 ngày dùng thử miễn phí.', morningBadBody:'Tiếc là đêm qua không ngon giấc. Tối nay muốn thử một chất âm khác không? Khung cảnh thành viên đồng hành suốt đêm. Gói năm kèm 3 ngày dùng thử miễn phí, hủy bất cứ lúc nào.', morningCta:'Tìm hiểu gói thành viên', morningLater:'Để sau', // v5 免费线·清醒预览制（2026-10-16 定稿，规格见 closed-testing-plan.md）
