      subscriptionUpgradeCancelOldReminder:'Nâng cấp gói đăng ký thành công! Nếu gói đăng ký cấp thấp hơn trước đây của bạn vẫn còn hoạt động, hãy nhớ hủy trong cài đặt hệ thống — nếu không bạn sẽ bị tính phí cho cả hai gói.',
