      diamondPerksList:'6 exclusieve nachtthema\'s om uit te kiezen, op elk moment te wisselen — een heel andere uitstraling dan elk ander niveau\nPersoonlijke, met de hand samengestelde geluidspresets die nergens anders te vinden zijn\nTot 60 opgeslagen mixen (standaardniveaus zijn beperkt tot 8 — in de praktijk zult je deze limiet vrijwel nooit bereiken)\nEen privékanaal van de oprichter — je hoort als eerste wat we aan het bouwen zijn\nEen Diamond-badge bij alles wat je deelt\nÉén "persoonlijk verzoek" per jaar — wij overwegen dit persoonlijk en serieus (geen garantie dat het wordt gerealiseerd)\nEen privé Diamond-ondersteuningspostbus — wij streven ernaar binnen 24 uur te reageren\nUw prijs wordt levenslang vastgezet, wat we nieuwe leden later ook vragen\nAls er ooit advertenties worden geïntroduceerd, zijn Diamond-leden daar permanent van uitgesloten',
