      planDiamond:'Diamond 💎', planDiamondBadge:'💎 Diamond',
      diamondPerksTeaser:'Mandhari za kipekee · Mipangilio ya sauti ya binafsi · Mawasiliano ya moja kwa moja na mwanzilishi · na zaidi',
      diamondDetailToggle:'Tazama faida zote za Diamond ▾', diamondDetailToggleOpen:'Funga ▴',
      diamondPerksList:'Mandhari 6 za usiku za kipekee kuchagua, badilisha wakati wowote — mwonekano tofauti kabisa na ngazi nyingine zote\nMipangilio ya sauti ya binafsi, iliyotengenezwa kwa makini, haipatikani mahali pengine\nHadi michanganyiko 60 iliyohifadhiwa (ngazi za kawaida zina kikomo cha 8 — kwa kawaida hautafikia kikomo hiki)\nMawasiliano ya binafsi ya mwanzilishi — unasikia kuhusu tunachokijenga kabla ya mtu mwingine yeyote\nAlama ya Diamond kwenye chochote unachoshiriki\nOmbi moja la kibinafsi kwa mwaka — tunalizingatia kwa dhati na kwa makini (hakuna ahadi litatekelezwa)\nSanduku la msaada la kipekee la Diamond — tunajitahidi kujibu ndani ya saa 24\nBei yako inakuwa ya kudumu maishani, haijalishi tutakachowatoza wanachama wapya baadaye\nIkiwa matangazo yataanzishwa siku moja, wanachama wa Diamond watasamehewa kabisa daima',
