      diamondPerksList:'Jigogi 6 na dare na musamman don zaɓa, canza su a kowane lokaci — kamanni daban da kowane matakin daban\nSaitunan sauti na keɓance, waɗanda aka tsara da hannu, waɗanda ba za ku samu wani wuri ba\nHar zuwa 60 cakuda da ake ajiye (matakan al\'ada suna da iyaka ta 8 — a zahiri ba za ku kai wannan iyaka ba)\nHanyar sirri ta wanda ya kafa — kuna jin abin da muke ginawa kafin kowa\nAlamar Diamond a duk abin da ku raba\nBuƙata ɗaya ta kashin ku a kowace shekara — muna duba ta da gaskiya kuma da muhimmanci (ba tabbacin za a gina ta ba)\nAkwatin tallafi na sirri na Diamond — muna ƙoƙari mu amsa cikin awa 24\nKuɗin ku zai kasance tsayayye har abada, komai yawan abin da za mu karɓa daga sababbin membobi daga baya\nIdan an gabatar da talla wata rana, membobin Diamond za su kasance an yafe su har abada',
