      previewEndedBody:'"{scene}" abun ciki ne na mambobi. Mambobi na saurare duka dare ba tare da katsewa ba. Shirin shekara yana da gwaji na kwana 3 kyauta, soke a kowane lokaci.', previewAgain:'Saurara kuma', previewUpgrade:'Bincika mambobi', mixTrackLimit:'Sigar kyauta na haɗa sauti 2 lokaci guda. Haɓaka don waƙoƙi marasa iyaka.', morningTitle:'Yaya barciyar daren jiya?', morningGood:'Daɗi ƙwarai', morningOk:'Tsaka-tsaka', morningBad:'Na sake yin barci mara kyau', morningGoodBody:'Muna farin ciki. Kuna son gwada ƙarin sautuna da yanayi? Mambobi na sauraren komai duka dare. Shirin shekara yana da gwaji na kwana 3 kyauta.', morningBadBody:'Mun yi haƙuri cewa daren bai yi kyau ba. Kuna son gwada wani nau\'in sauti na daban a daren yau? Yanayin mambobi na rakiya duka dare. Shirin shekara da gwaji na kwana 3 kyauta, soke a kowane lokaci.', morningCta:'Bincika mambobi', morningLater:'Wataƙila daga baya', // v5 免费线·清醒预览制（2026-10-16 定稿，规格见 closed-testing-plan.md）
